('tour','97c63004-427b-4de7-ae84-8a95425d56a8','en','title',$j$"The Fire Route: Exploring Fageda d'en Jordà and Castellfollit de la Roca"$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','en','area',$j$"La Garrotxa"$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','en','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Arrive 15 minutes early."$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','en','inclusions',$j$["Return coach from Barcelona", "Accompanying guide"]$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','en','exclusions',$j$["Food and drinks"]$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','en','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🌋 Fageda d'en Jordà: A Geological Mystery for Your Group", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "The beech forest of the Fageda d'en Jordà is no ordinary forest; it is a ", "type": "text"}, {"text": "unique geological exploration area", "type": "text", "marks": [{"type": "bold"}]}, {"text": " lying on an ancient solidified lava flow from the Croscat volcano. At an altitude of 550 metres, it is an unusual and rare terrain on the Iberian Peninsula. As part of the La Garrotxa region, we are surrounded by 21 volcanic craters, a feature that inspires adventure and discovery. This setting has been a source of inspiration for artists and historians.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🔥 The Santa Margarida Volcano: Team Cohesion in the Crater", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "In this impressive volcanic setting, we highlight the ", "type": "text"}, {"text": "Santa Margarida volcano", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Its eruption left a wide, circular crater, with a Romanesque hermitage inside. Beyond the meadow that now fills the crater, the rest of the volcano is covered by deciduous forest. Our exploration route takes you to the Santa Margarida Area (following part of itinerary 3), an ideal stretch for ", "type": "text"}, {"text": "team building activities", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and experience the true essence of this area.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🧱 Castellfollit de la Roca: The Basalt Bastion", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Perched on the edge of a 50-metre-high basalt cliff carved by the river Fluvià, ", "type": "text"}, {"text": "Castellfollit de la Roca", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is one of the smallest and most fascinating villages in the province of Girona. The village sits on two superimposed lava flows that give it a dramatic silhouette. Its old town, built with volcanic stone, takes us back to the 11th century and lets our group explore history from the main street to the Josep Pla viewpoint. ", "type": "text"}, {"text": "It is the perfect end to a day of geological exploration.", "type": "text", "marks": [{"type": "bold"}]}]}]}]}$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','en','title',$j$"The Pyrenees Challenge: Exploring Queralbs and the Legendary Vall de Núria"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','en','area',$j$"Ripollès"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','en','difficulty',$j$"Medium (optional hike)"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','en','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Arrive 15 minutes early."$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','en','inclusions',$j$["Return coach from Barcelona", "Accompanying guide", "Return rack railway ticket", "Cable car inside Vall de Núria"]$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','en','exclusions',$j$["Food and drinks"]$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','en','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏔️ Queralbs: The Stone Treasure of the Pyrenees", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Our starting point is ", "type": "text"}, {"text": "Queralbs", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", a historic treasure at 1,220 metres above sea level in the Ripollès region. With stone houses and slate roofs, Queralbs is one of the most picturesque villages in the Catalan Pyrenees. Documented since the year 839, this village offers a glimpse of local history. Here we will explore its heritage, highlighting the ", "type": "text"}, {"text": "Church of Sant Jaume (10th c.)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and its town hall, preparing our group for the big climb.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚠 Vall de Núria: Adventure at 2,000 Metres (Team Only!)", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "The main activity is the ascent to ", "type": "text"}, {"text": "Vall de Núria", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", an idyllic spot at almost 2,000 metres, surrounded by peaks reaching 3,000 metres. This valley is one of the most emblematic and beautiful landscapes in Catalonia. Here, your group can enjoy all kinds of ", "type": "text"}, {"text": "adventure sports, hiking and team-bonding activities", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". In addition to visiting the historic Núria Sanctuary, this setting offers the perfect opportunity for team exploration.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚂 Logistics and Ascent: The Rack Railway", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "To go up to the valley, we will use the ", "type": "text"}, {"text": "Rack Railway", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", since access by car is not allowed, ensuring organised and efficient transport logistics for our group of 55 people. For the more adventurous, there is the option to walk up from Queralbs on a route of about 4 hours (medium level, 800 m of elevation gain). ", "type": "text"}, {"text": "The rack railway ticket and the cable car ride inside Vall de Núria are included in the price", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", so you can enjoy the views without paying anything more.", "type": "text"}]}]}]}$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','en','title',$j$"The Wild Heart of the Pyrenees: Aigüestortes and Lake Sant Maurici"$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','en','area',$j$"Pallars"$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','en','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Arrive 15 minutes early."$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','en','inclusions',$j$["Return coach from Barcelona", "Accompanying guide", "4x4 taxi Espot – Estany de Sant Maurici"]$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','en','exclusions',$j$["Food and drinks"]$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','en','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏞️ Aigüestortes: The Only National Park in Catalonia", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Tripcelona invites you on an adventure in the heart of the Central Pyrenees, in the Aigüestortes i Estany de Sant Maurici National Park.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Declared a National Park on 21 October 1955, it is the only national park in Catalonia and one of the most emblematic in Spain. It covers more than 40,000 hectares in the province of Lleida, spanning the territories of Alta Ribagorça, Pallars Sobirà, Pallars Jussà and the Val d'Aran.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "💧 The Famous 'Winding Waters' Route", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "The park's name, ", "type": "text"}, {"text": "\"Aigüestortes\"", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", literally means ", "type": "text"}, {"text": "\"Winding Waters\"", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", referring to the many rivers, streams and channels that wind through its valleys, creating unique landscapes. The park is of glacial origin and offers your group an incomparable exploration experience, with ", "type": "text"}, {"text": "more than 200 lakes (estanys)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", dense fir and beech forests, and peaks exceeding ", "type": "text"}, {"text": "3,000 metres", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "⛰️ Sant Maurici and Els Encantats: The Symbol of the Expedition", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "The most iconic place in the park is ", "type": "text"}, {"text": "Estany de Sant Maurici", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". The beauty of the bay is enhanced by the majestic ", "type": "text"}, {"text": "Encantats", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", two twin mountains with pointed shapes that dominate the landscape and stand at ", "type": "text"}, {"text": "1,910 metres above sea level", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". In this setting, we organise hiking and photography routes ideal for ", "type": "text"}, {"text": "Team Building", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and total immersion in the wild nature of the Pyrenees.", "type": "text"}]}]}]}$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','en','title',$j$"The Vero Canyon: Alquézar and the Walkways Route"$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','en','area',$j$"Huesca (Aragon)"$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','en','difficulty',$j$"Easy to moderate"$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','en','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Arrive 15 minutes early."$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','en','inclusions',$j$["Return coach from Barcelona", "Accompanying guide"]$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','en','exclusions',$j$["Food and drinks"]$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','en','packing_list',$j$["Hiking boots", "Warm clothing"]$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','en','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏰 Alquézar: The Medieval Town Hanging Over the Canyon", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "We cross into Aragon to reach ", "type": "text"}, {"text": "Alquézar", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", in the heart of the Somontano and the ", "type": "text"}, {"text": "Sierra and Canyons of Guara Natural Park", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Considered one of the most beautiful villages in Spain, Alquézar rises on a rock, crowned by its ", "type": "text"}, {"text": "Collegiate Church of Santa María", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and the remains of its castle of Muslim origin. As a group we will walk its cobbled streets, arcaded squares and viewpoints over the canyon before going down to the river.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🌉 Walkways Route: Walking Above the Vero River", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "The big adventure of the day is the ", "type": "text"}, {"text": "Vero River Walkways Route", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", a circular route along metal walkways anchored to the canyon walls, stairs and suspension bridges over turquoise waters. We will go down to the bottom of the canyon, pass by waterfalls and centuries-old dams, and walk beneath huge rock overhangs. It is a spectacular route to do as a team, full of corners for the best group photos.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🦅 Sierra de Guara: Wild Nature and Griffon Vultures", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "During the route it is common to see ", "type": "text"}, {"text": "griffon vultures", "type": "text", "marks": [{"type": "bold"}]}, {"text": " flying over the canyon. We will stop for lunch (lunch not included: you can bring a picnic or eat at the village's bars and restaurants) and have free time to enjoy Alquézar before returning to Barcelona.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚌 Logistics: A Full Day Without Worries", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "We leave by coach from Estació del Nord and reach Alquézar in about 3 hours, with a rest stop on the way. Our guide accompanies the group throughout the day. ", "type": "text"}, {"text": "In winter, the opening of the walkways depends on the weather and the river flow", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": if it is not possible to walk them, we will take an alternative route along the viewpoints and trails of the Vero canyon.", "type": "text"}]}]}, {"type": "paragraph", "content": [{"text": "Photos: FrDr, Robot8A, Mikipons, McBodes, Augustin Liviu, Alberto-g-rovi, Pedro José Ponce Asensio, Enric, LSanzSal — Wikimedia Commons (CC BY / CC BY-SA licences).", "type": "text"}]}]}$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','en','title',$j$"The Rural Magic of Catalonia: A Getaway to Rupit and Tavertet"$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','en','area',$j$"Osona"$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','en','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Arrive 15 minutes early."$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','en','inclusions',$j$["Return coach from Barcelona", "Accompanying guide"]$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','en','exclusions',$j$["Food and drinks"]$j$::jsonb),
('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','en','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏰 Rupit: The Medieval Jewel of the Collsacabra", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Our exploration begins in ", "type": "text"}, {"text": "Rupit", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", a charming medieval village recognised worldwide (UN Tourism included it among the «Best Tourism Villages» in the world). Walking through Rupit, your group will be immersed in a spectacular natural setting where time seems to have stopped. It is a cultural immersion experience, with its narrow streets, stone houses and suspension bridges that invite historical exploration. Rupit is not just a place, it is a step back into Catalan rural history.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "⛰️ Tavertet: The Geographic Viewpoint Hanging in the Air", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "The adventure reaches its peak in ", "type": "text"}, {"text": "Tavertet", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", an impressive village perched on top of a ", "type": "text"}, {"text": "natural crag (cliff)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". This unique geographic location makes Tavertet an unrivalled viewpoint. From here, your group will enjoy ", "type": "text"}, {"text": "panoramic views", "type": "text", "marks": [{"type": "bold"}]}, {"text": " over the vast reservoirs of ", "type": "text"}, {"text": "Sau", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Susqueda", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", and will be able to contemplate the majesty of the ", "type": "text"}, {"text": "Montseny", "type": "text", "marks": [{"type": "bold"}]}, {"text": " range on the horizon. This location is ideal for reflecting on the magnitude of Catalan nature and capturing stunning group photographs.", "type": "text"}]}]}]}$j$::jsonb),
