('faq','ec0aac39-c857-486f-8a1c-5ce40e19913a','en','question',$j$"Are there any requirements to travel with Tripcelona?"$j$::jsonb),
('faq','ec0aac39-c857-486f-8a1c-5ce40e19913a','en','answer',$j$"Apart from paying the price of each exploration route, the most important requirement we ask for is enthusiasm, a desire to discover new places and a spirit of group adventure."$j$::jsonb),
('faq','ddda2ac7-456b-48b9-b545-e10cdd079c53','en','question',$j$"Is there a minimum or maximum age to take part?"$j$::jsonb),
('faq','ddda2ac7-456b-48b9-b545-e10cdd079c53','en','answer',$j$"The minimum age to take part in our trips is 3 years. There is no maximum age."$j$::jsonb),
('faq','b05f3306-76a4-43ad-870a-868b933c74c5','en','question',$j$"Is there a discount for children under 10?"$j$::jsonb),
('faq','b05f3306-76a4-43ad-870a-868b933c74c5','en','answer',$j$"All our travellers pay the same price, since the seat they occupy is essential to the group's transport logistics, without exception."$j$::jsonb),
('faq','4f9b83f8-e61d-4e25-bc8a-1fe3093e9bbd','en','question',$j$"Are pets allowed on the routes?"$j$::jsonb),
('faq','4f9b83f8-e61d-4e25-bc8a-1fe3093e9bbd','en','answer',$j$"We are animal lovers, but for the moment it is not possible for them to travel with us on the bus."$j$::jsonb),
('faq','e1eda4bf-7fdc-492a-bbef-63156683d4b7','en','question',$j$"How can we book and pay for a trip?"$j$::jsonb),
('faq','e1eda4bf-7fdc-492a-bbef-63156683d4b7','en','answer',$j$"Choose the excursion in Trip offers, press «Book a place», fill in the participants' details and pay by card. Your place is confirmed the moment you pay."$j$::jsonb),
('faq','57328765-dde8-4701-b9e0-084cba680258','en','question',$j$"What payment methods do you accept?"$j$::jsonb),
('faq','57328765-dde8-4701-b9e0-084cba680258','en','answer',$j$"We accept payment by credit or debit card (Visa, Mastercard and Maestro) through our bank's secure payment gateway. For large group quotes or companies, write to us and we will tell you the available options."$j$::jsonb),
('faq','3ea3574c-a182-44b5-9aab-8bce283f54c3','en','question',$j$"How far in advance should I book?"$j$::jsonb),
('faq','3ea3574c-a182-44b5-9aab-8bce283f54c3','en','answer',$j$"We have limited places on all our routes. We recommend not waiting, as places, especially for large groups, tend to sell out quickly."$j$::jsonb),
('faq','2573694a-c31a-4816-bee7-3581eef15233','en','question',$j$"How do I know my place is booked and paid for?"$j$::jsonb),
('faq','2573694a-c31a-4816-bee7-3581eef15233','en','answer',$j$"Once the payment is made, you will receive a confirmation email from contact.achrafmsr@gmail.com. This usually takes 2 to 3 hours. If the purchase is made at night, you will receive the confirmation the next day."$j$::jsonb),
('faq','850fe5c4-e9f2-4868-834d-6b87c1f0b151','en','question',$j$"Will I receive confirmation of my booking?"$j$::jsonb),
('faq','850fe5c4-e9f2-4868-834d-6b87c1f0b151','en','answer',$j$"Yes, once the payment is made, you will receive a confirmation of your place by email."$j$::jsonb),
('faq','3de170ec-ab5a-4d60-9c0d-72e814e7e061','en','question',$j$"Where do our trips start?"$j$::jsonb),
('faq','3de170ec-ab5a-4d60-9c0d-72e814e7e061','en','answer',$j$"Our routes start at Avenida de la Reina María Cristina, in Plaza España (next to the Venetian Towers). You must be at the spot with the Tripcelona guide 20 minutes before the scheduled departure time."$j$::jsonb),
('faq','9b804f5a-d1f8-4b7d-a212-4c47b3aa76bb','en','question',$j$"Where do the trips end?"$j$::jsonb),
('faq','9b804f5a-d1f8-4b7d-a212-4c47b3aa76bb','en','answer',$j$"They end at the same place they start: Avenida de la Reina María Cristina, next to the Venetian Towers."$j$::jsonb),
('faq','4e95e71d-6216-48dd-8477-8ec4ce7890b2','en','question',$j$"How do I find the guide on the day of the route?"$j$::jsonb),
('faq','4e95e71d-6216-48dd-8477-8ec4ce7890b2','en','answer',$j$"The Tripcelona guide will be waiting for you at Avenida de la Reina María Cristina, 20 minutes before departure. The bus will also be identified."$j$::jsonb),
('faq','e1d1f3ff-cdbe-4267-ae61-79b1ec5cb09f','en','question',$j$"Is there a guide on the exploration route?"$j$::jsonb),
('faq','e1d1f3ff-cdbe-4267-ae61-79b1ec5cb09f','en','answer',$j$"On every Tripcelona route we have a specialised local guide who provides key information about the places we visit, offers maps and recommends authentic spots for the group."$j$::jsonb),
('faq','bada6c59-42c1-47b8-93c7-e51cddd81eca','en','question',$j$"Do the buses have a toilet (WC)?"$j$::jsonb),
('faq','bada6c59-42c1-47b8-93c7-e51cddd81eca','en','answer',$j$"We are sorry to tell you that the buses we use do not have toilets. For this reason, on journeys longer than two hours we always make a rest stop for a break and use of the restroom."$j$::jsonb),
('faq','f8ba5998-db46-4087-b958-be859f5ff283','en','question',$j$"What happens if the weather is bad (rain, snow)?"$j$::jsonb),
('faq','f8ba5998-db46-4087-b958-be859f5ff283','en','answer',$j$"Excursions take place in rain or cold, so we recommend checking the forecast and coming well equipped. Bad weather does not entitle you to cancel with a refund. If conditions are not safe, Tripcelona will cancel or change the date and you will be able to choose between a new date or a 100% refund."$j$::jsonb),
('faq','15eeb341-069e-4dc3-811e-73784ffba0bd','en','question',$j$"What is the cancellation policy?"$j$::jsonb),
('faq','15eeb341-069e-4dc3-811e-73784ffba0bd','en','answer',$j$"• More than 15 days before the excursion: 100% refund.\n\n• 15 days or less before, or no-show: no refund.\n\n• You can transfer your place to another person at no cost by notifying us at least 10 days in advance.\n\nMore information in the Cancellation and refund policy."$j$::jsonb),
('faq','c4c595ae-8e42-44db-b825-078e0282aae6','en','question',$j$"What happens if I buy a trip less than 15 days before?"$j$::jsonb),
('faq','c4c595ae-8e42-44db-b825-078e0282aae6','en','answer',$j$"If you book when 15 days or less remain, the booking is non-refundable. Even so, you can transfer your place to another person by letting us know by email."$j$::jsonb),
('faq','b3bd5900-fc43-4341-b854-ff1b9c94cb51','en','question',$j$"What happens if I cannot attend for personal reasons (e.g. Covid)?"$j$::jsonb),
('faq','b3bd5900-fc43-4341-b854-ff1b9c94cb51','en','answer',$j$"If you let us know more than 15 days in advance, we refund 100%. With 15 days or less there is no refund, whatever the reason, but you can transfer your place to another person."$j$::jsonb),
('faq','473ee461-5036-4212-ac43-a628f705a03b','en','question',$j$"If I arrive late, is there a refund?"$j$::jsonb),
('faq','473ee461-5036-4212-ac43-a628f705a03b','en','answer',$j$"No. On our routes, we do not wait more than 10 minutes after the scheduled departure time. If you arrive late, you will lose 100% of the money paid."$j$::jsonb),
('faq','59107c8e-abf9-4dc4-9b30-8b997bb5cf81','en','question',$j$"What happens if I miss the return bus?"$j$::jsonb),
('faq','59107c8e-abf9-4dc4-9b30-8b997bb5cf81','en','answer',$j$"If you are not at the meeting point at the agreed return time, you will have to make your own way back. We wait a maximum of 10 minutes."$j$::jsonb),
('faq','3278a963-b9c1-44ca-99d2-f76c579d6128','en','question',$j$"How can I contact you?"$j$::jsonb),
('faq','3278a963-b9c1-44ca-99d2-f76c579d6128','en','answer',$j$"Write to us at contact.achrafmsr@gmail.com or call us on +34 666 69 69 54 (also on WhatsApp)."$j$::jsonb),
('post','4b46ce44-57b7-4fc2-98f2-d2d129e61337','en','title',$j$"What to bring on a day trip: the complete list"$j$::jsonb),
('post','4b46ce44-57b7-4fc2-98f2-d2d129e61337','en','excerpt',$j$"Backpack, layered clothing, food and footwear: the practical list of everything you need for a day trip to the mountains from Barcelona."$j$::jsonb),
('post','4b46ce44-57b7-4fc2-98f2-d2d129e61337','en','seo_title',$j$"What to bring on a day trip: complete list"$j$::jsonb),
('post','4b46ce44-57b7-4fc2-98f2-d2d129e61337','en','seo_description',$j$"Practical list of what to bring on a day trip: backpack, water, food, layered clothing, footwear and sun protection."$j$::jsonb),
('post','4b46ce44-57b7-4fc2-98f2-d2d129e61337','en','content',$j${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "A good excursion starts the night before, packing your backpack. If it is your first outing to the mountains or countryside from Barcelona, here is a simple list of what you need to enjoy yourself without getting cold, hungry or caught out.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The essentials", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Small backpack", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (20–30 litres) with two straps.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Water", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": at least 1–1.5 litres per person.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Food", "type": "text", "marks": [{"type": "bold"}]}, {"text": ": a sandwich, fruit and something energising (nuts, bars).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "ID document", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and your ticket (on your phone or printed).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Phone with a charged battery", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and, if you can, a power bank.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Cash or card", "type": "text", "marks": [{"type": "bold"}]}, {"text": " for a coffee or a souvenir.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Clothing: think in layers", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In the mountains the temperature can be 10 °C lower than in Barcelona, and it changes quickly. The trick is to dress in layers:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Breathable T-shirt (better than cotton).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fleece or jumper.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Windproof or waterproof jacket.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hat and gloves in autumn and winter; cap in summer.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Footwear", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trekking shoes or boots with a good sole. Avoid wearing new shoes on the day of the excursion: they can cause blisters.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Protection", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sunscreen (even if it is cloudy).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sunglasses.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Small first-aid kit: plasters, painkiller and your usual medication.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "On the day of departure", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Have a good breakfast and arrive at the meeting point, ", "type": "text"}, {"text": "Estació del Nord (C/ d'Alí Bei 80)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", about 15 minutes early. Have your ticket with the QR code at hand: we scan it when you board the coach.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Ready for your next adventure?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "You have the backpack. Now you just need to choose a destination.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "See upcoming excursions", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/ofertas-de-viajes"}}]}]}]}$j$::jsonb),
('post','cbfc4e85-3c24-4ff5-8989-684336fab0d9','en','title',$j$"Rupit and Tavertet: two charming villages in the Collsacabra"$j$::jsonb),
('post','cbfc4e85-3c24-4ff5-8989-684336fab0d9','en','excerpt',$j$"A medieval village with a suspension bridge and another perched on the cliffs: what to see in Rupit and Tavertet on a day trip from Barcelona."$j$::jsonb),
('post','cbfc4e85-3c24-4ff5-8989-684336fab0d9','en','seo_title',$j$"Rupit and Tavertet: what to see on a trip from Barcelona"$j$::jsonb),
('post','cbfc4e85-3c24-4ff5-8989-684336fab0d9','en','seo_description',$j$"Guide to visiting Rupit and Tavertet in one day: the suspension bridge, the Salt de Sallent, the viewpoints over the Sau reservoir and practical tips."$j$::jsonb),
('post','cbfc4e85-3c24-4ff5-8989-684336fab0d9','en','content',$j${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "In the Osona region, on the ", "type": "text"}, {"text": "Collsacabra", "type": "text", "marks": [{"type": "bold"}]}, {"text": "plateau, there are two villages that seem frozen in time: ", "type": "text"}, {"text": "Rupit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and ", "type": "text"}, {"text": "Tavertet", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". One is a medieval stone labyrinth; the other, a natural balcony over the void. Together they make one of the most beautiful day trips from Barcelona.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Rupit: the medieval stone village", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Rupit is one of the most photographed villages in Catalonia. You enter by crossing a ", "type": "text"}, {"text": "suspension bridge", "type": "text", "marks": [{"type": "bold"}]}, {"text": " over the stream, and from there everything is cobbled streets, stairs carved into the rock, wooden balconies with flowers and houses from the 16th and 17th centuries.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Don't miss the carrer del Fossar, which climbs carved into the rock up to the church of Sant Miquel, nor the walk to the ", "type": "text"}, {"text": "Salt de Sallent", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", a nearby waterfall of about 100 metres when it is flowing.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tavertet: perched on the cliffs", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tavertet is a tiny village built right on the edge of the Collsacabra cliffs. From its viewpoints you can see the Ter valley, the ", "type": "text"}, {"text": "Sau reservoir", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and, on clear days, the Montseny mountains. It is a place to stroll slowly, breathe and take photos.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tips for the visit", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Rupit has lots of slopes and stairs: wear comfortable footwear.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Try the local cuisine: the area is known for its cured meats and mountain dishes.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Respect the residents: these are small villages where people live all year round.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bring a jacket: on the plateau it is usually cooler than on the coast.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Escape with Tripcelona", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Rural Magic of Catalonia", "type": "text", "marks": [{"type": "bold"}]}, {"text": " takes you to Rupit and Tavertet by coach from Estació del Nord with an accompanying guide. A Sunday of charming villages without a worry in the world.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "See The Rural Magic of Catalonia", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/excursiones/la-magia-rural-de-cataluna-escapada-a-rupit-y-tavertet"}}]}]}]}$j$::jsonb),
('post','b7b18f07-6f97-4b16-b8f6-0a0ad1b4999d','en','title',$j$"Vall de Núria and Queralbs: how to visit the Pyrenean valley with no roads"$j$::jsonb),
('post','b7b18f07-6f97-4b16-b8f6-0a0ad1b4999d','en','excerpt',$j$"A valley at 2,000 metres that can only be reached by rack railway or on foot. Everything you need to know to visit Queralbs and Vall de Núria in one day."$j$::jsonb),
('post','b7b18f07-6f97-4b16-b8f6-0a0ad1b4999d','en','seo_title',$j$"Vall de Núria and Queralbs: day trip from Barcelona"$j$::jsonb),
('post','b7b18f07-6f97-4b16-b8f6-0a0ad1b4999d','en','seo_description',$j$"How to get to Vall de Núria, what to see in Queralbs and what to bring. A guide to doing the trip as a group from Barcelona."$j$::jsonb),
('post','b7b18f07-6f97-4b16-b8f6-0a0ad1b4999d','en','content',$j${"type": "doc", "content": [{"type": "image", "attrs": {"alt": "", "src": "https://tripcelona.com/wp-content/uploads/2025/11/volca_15_630x420.jpeg", "title": null}}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Vall de Núria", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is one of the most special places in the Catalan Pyrenees: a valley at around 2,000 metres, surrounded by peaks of almost 3,000 metres, which cannot be reached by car. If you want to experience the high mountains on a day trip from Barcelona, this is your route.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How to get to Núria", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Núria can only be reached in two ways:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On the Núria rack railway", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", the rack train that departs from Ribes de Freser and stops at Queralbs. The journey climbs the Núria river valley with impressive views.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "On foot", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", along the old pilgrims' path that climbs from Queralbs beside the river, passing through gorges and waterfalls. It is a demanding walk with a considerable elevation gain.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Queralbs: the stone village", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Queralbs, at around 1,200 metres, is a small village of stone houses and slate roofs. Its Romanesque church of Sant Jaume and its quiet streets make it a perfect stop before going up to the valley.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What to do in Vall de Núria", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Visit the ", "type": "text"}, {"text": "Núria sanctuary", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and the image of the Virgin, much loved in Catalonia.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Stroll around the ", "type": "text"}, {"text": "lake", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and take the classic photo with the sanctuary reflected in it.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Do a short route through the meadows, for example towards the Sant Gil hermitage.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "For the better prepared, the valley is a starting point towards summits such as the Puigmal.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "What to bring", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In Núria the weather changes quickly and it is always colder than in Barcelona. Bring layers of clothing, a raincoat, sunglasses, sunscreen, water and mountain footwear. In winter, snow clothing.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Experience The Pyrenees Challenge with Tripcelona", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Our excursion departs from Estació del Nord, in Barcelona, with transport and guide, so that your group only has to worry about enjoying the mountains.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "See The Pyrenees Challenge", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/excursiones/el-reto-del-pirineo-exploracion-de-queralbs-y-el-mitico-vall-de-nuria"}}]}]}]}$j$::jsonb),
('post','54c276fc-ef2a-49e0-bcd6-a63e7e1fdd2a','en','title',$j$"Aigüestortes and Lake Sant Maurici: guide to the only national park in Catalonia"$j$::jsonb),
('post','54c276fc-ef2a-49e0-bcd6-a63e7e1fdd2a','en','excerpt',$j$"Glacial lakes, the legend of Els Encantats and routes for all levels: guide to visiting Aigüestortes and Lake Sant Maurici."$j$::jsonb),
('post','54c276fc-ef2a-49e0-bcd6-a63e7e1fdd2a','en','seo_title',$j$"Aigüestortes and Lake Sant Maurici: guide and excursion"$j$::jsonb),
('post','54c276fc-ef2a-49e0-bcd6-a63e7e1fdd2a','en','seo_description',$j$"What to see in the Aigüestortes i Estany de Sant Maurici National Park, how to visit it and tips for going as a group from Barcelona."$j$::jsonb),
('post','54c276fc-ef2a-49e0-bcd6-a63e7e1fdd2a','en','content',$j${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Aigüestortes i Estany de Sant Maurici National Park", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the only national park in Catalonia and one of the most beautiful high-mountain landscapes in the Peninsula. Glacial lakes, rivers winding between meadows and granite peaks: this is the wild heart of the Pyrenees.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "A park of lakes", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The park has nearly 200 lakes (in Catalan, \"estanys\") of glacial origin. Its name, Aigüestortes, means \"winding waters\" and refers to the meanders formed by the rivers on the high-mountain plains.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Lake Sant Maurici and Els Encantats", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The park's most famous image is the ", "type": "text"}, {"text": "Estany de Sant Maurici", "type": "text", "marks": [{"type": "bold"}]}, {"text": " with the two spires of ", "type": "text"}, {"text": "Els Encantats", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the background. Legend has it that they are two hunters who escaped from Mass to go hunting and were turned to stone. Whatever the story, the view is spectacular.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "How to visit", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Access to the central areas of the park by private vehicle is restricted to protect the environment, and authorised 4x4 taxis are used or you walk. From the Espot area, the eastern entrance, you reach Sant Maurici and routes for all levels set out.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tips", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Respect the park rules: swimming in the lakes and leaving the marked paths is not allowed.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bring warm layers, a raincoat and sun protection: at this altitude the sun is strong.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mountain footwear with a good sole.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Take your rubbish back with you.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Explore Aigüestortes with Tripcelona", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "With ", "type": "text"}, {"text": "The Wild Heart of the Pyrenees", "type": "text", "marks": [{"type": "bold"}]}, {"text": " you go by coach from Barcelona with a guide and return the same day. No driving on mountain passes.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "See The Wild Heart of the Pyrenees", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/excursiones/el-corazon-salvaje-del-pirineo-aiguestortes-y-el-lago-de-sant-maurici"}}]}]}]}$j$::jsonb),
('post','ed6f7edb-5697-462c-bade-21011b45b52b','en','title',$j$"Fageda d'en Jordà and Castellfollit de la Roca: excursion to volcanic La Garrotxa"$j$::jsonb),
('post','ed6f7edb-5697-462c-bade-21011b45b52b','en','excerpt',$j$"A beech forest growing on lava and a village on the edge of a basalt cliff: guide to visiting the Fageda d'en Jordà and Castellfollit de la Roca in one day from Barcelona."$j$::jsonb),
('post','ed6f7edb-5697-462c-bade-21011b45b52b','en','seo_title',$j$"Fageda d'en Jordà and Castellfollit de la Roca: excursion guide"$j$::jsonb),
('post','ed6f7edb-5697-462c-bade-21011b45b52b','en','seo_description',$j$"How to visit the Fageda d'en Jordà and Castellfollit de la Roca in one day from Barcelona: what to see, best season and tips for going as a group."$j$::jsonb),
('post','ed6f7edb-5697-462c-bade-21011b45b52b','en','content',$j${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "If you are looking for an excursion from Barcelona that combines forest, volcanoes and a spectacular village, La Garrotxa is a sure bet. In a single day you can walk through the ", "type": "text"}, {"text": "Fageda d'en Jordà", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and end up in front of the cliff of ", "type": "text"}, {"text": "Castellfollit de la Roca", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". We tell you what to see and how to organise it.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "The Garrotxa Volcanic Zone", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The La Garrotxa region, in Girona, is home to the La Garrotxa Volcanic Zone Natural Park, with dozens of volcanic cones and lava flows. The volcanoes have been dormant for thousands of years and are now covered in forest, which gives the landscape a soft, green look very different from what you imagine when you think of volcanoes.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Fageda d'en Jordà: a beech forest on lava", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The Fageda d'en Jordà is a beech forest that grows on the lava flow of the Croscat volcano. The curious thing is that beeches normally live at higher altitudes; here they thrive thanks to the humidity and the volcanic soil. The result is a dense forest, with the ground rippled by small mounds of solidified lava (the \"tossols\").", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The walk is flat and suitable for almost everyone. ", "type": "text"}, {"text": "The best time is autumn", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", when the leaves turn golden, coppery and red, although in spring the intense green is also lovely.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Castellfollit de la Roca: the village on the edge of the abyss", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Castellfollit is built on a basalt crag about 50 metres high and around a kilometre long, formed by two superimposed lava flows. The houses literally reach the edge. It is worth seeing it from below, next to the river Fluvià, and then going up to the viewpoint next to the church of Sant Salvador.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Tips for the excursion", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Footwear:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " comfortable shoes; the path can be muddy if it has rained.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Clothing:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the forest it is cooler than in Barcelona, bring an extra layer.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Food:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " bring a sandwich or eat in Castellfollit or Olot.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Camera:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " the light among the beeches in mid-morning is spectacular.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Do it with Tripcelona", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Our excursion ", "type": "text"}, {"text": "The Fire Route", "type": "text", "marks": [{"type": "bold"}]}, {"text": " departs by coach from Estació del Nord, in Barcelona, with an accompanying guide and returns the same day. You just have to enjoy it.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Book The Fire Route", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/excursiones/la-ruta-del-fuego-exploracion-en-fageda-den-jorda-y-castellfollit-de-la-roca"}}]}]}]}$j$::jsonb),
('post','e32aba65-b6f8-416d-8114-9ae586362602','en','title',$j$"The best group day trips from Barcelona"$j$::jsonb),
('post','e32aba65-b6f8-416d-8114-9ae586362602','en','excerpt',$j$"Volcanoes, Pyrenean lakes and medieval villages: the best day trips from Barcelona to do as a group, without a car and with a guide."$j$::jsonb),
('post','e32aba65-b6f8-416d-8114-9ae586362602','en','seo_title',$j$"Group day trips from Barcelona | Tripcelona"$j$::jsonb),
('post','e32aba65-b6f8-416d-8114-9ae586362602','en','seo_description',$j$"Discover the best day trips from Barcelona: La Garrotxa, Vall de Núria, Aigüestortes and Rupit. By coach, with a guide and in a group."$j$::jsonb),
('post','e32aba65-b6f8-416d-8114-9ae586362602','en','content',$j${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Barcelona is an incredible city, but just two or three hours away by coach you have dormant volcanoes, high-mountain lakes, valleys that can only be reached by rack railway and medieval villages hanging from a precipice. If you want to leave the city on a Sunday without having to organise anything, in this guide we tell you about the best day trips from Barcelona to do as a group.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "All the routes on this list depart from ", "type": "text"}, {"text": "Estació del Nord (C/ d'Alí Bei 80, Barcelona)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in the morning and return the same day. No nights away, no car and no worrying about parking.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "1. La Garrotxa: Fageda d'en Jordà and Castellfollit de la Roca", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The La Garrotxa Volcanic Zone is one of the most surprising landscapes in Catalonia. The ", "type": "text"}, {"text": "Fageda d'en Jordà", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a beech forest growing on an ancient lava flow, which is unusual because beeches tend to live in higher areas. In autumn the forest turns golden and red, and it is one of the most photogenic walks in the region.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The route ends in ", "type": "text"}, {"text": "Castellfollit de la Roca", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", a village built on a basalt crag about 50 metres high and almost a kilometre long. The view from below is the kind you don't forget.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ideal for:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " groups looking for nature without a big elevation gain. 👉 ", "type": "text"}, {"text": "See the excursion The Fire Route", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/excursiones/la-ruta-del-fuego-exploracion-en-fageda-den-jorda-y-castellfollit-de-la-roca"}}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "2. Queralbs and Vall de Núria", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Vall de Núria", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is a Pyrenean valley at about 2,000 metres of altitude that no road reaches: you go up on the rack railway from Ribes de Freser or Queralbs, or on foot along the old pilgrims' path beside the river. At the top the sanctuary, the lake and meadows surrounded by peaks await you.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Before that, a stop in ", "type": "text"}, {"text": "Queralbs", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", a small stone village at about 1,200 metres that looks like something out of a fairy tale.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ideal for:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " groups who want real mountains. 👉 ", "type": "text"}, {"text": "See the excursion The Pyrenees Challenge", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/excursiones/el-reto-del-pirineo-exploracion-de-queralbs-y-el-mitico-vall-de-nuria"}}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "3. Aigüestortes and Lake Sant Maurici", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The ", "type": "text"}, {"text": "Aigüestortes i Estany de Sant Maurici National Park", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is the only national park in Catalonia. Its name (\"winding waters\") comes from the rivers that wind through high-mountain meadows, and it has nearly 200 lakes of glacial origin. Lake Sant Maurici, with the peaks of Els Encantats reflected in the water, is its most famous image.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ideal for:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " hiking and photography lovers. 👉 ", "type": "text"}, {"text": "See the excursion The Wild Heart of the Pyrenees", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/excursiones/el-corazon-salvaje-del-pirineo-aiguestortes-y-el-lago-de-sant-maurici"}}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "4. Rupit and Tavertet", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Rupit", "type": "text", "marks": [{"type": "bold"}]}, {"text": " is one of the best-preserved medieval villages in Catalonia: cobbled streets, stone houses and its famous suspension bridge over the stream. Very close by is ", "type": "text"}, {"text": "Tavertet", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", a small village perched on the Collsacabra cliffs, with views over the Sau reservoir and, on clear days, as far as the Montseny.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ideal for:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " a relaxed day of villages, history and viewpoints. 👉 ", "type": "text"}, {"text": "See the excursion The Rural Magic of Catalonia", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/excursiones/la-magia-rural-de-cataluna-escapada-a-rupit-y-tavertet"}}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Why do these excursions as a group?", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "No car or parking:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " the coach takes you and brings you back from the centre of Barcelona.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "A guide who knows the area:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " you know where to stop, what to see and how much time you have.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fixed price:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " you know what you pay from the start.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "New people:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " perfect if you come alone, with friends or with your work team.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Quick tips before you leave", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bring comfortable footwear, water, some food and a warm layer: in the mountains the temperature changes quickly. Arrive at Estació del Nord about 15 minutes before departure. If you want more details, read our guide ", "type": "text"}, {"text": "what to bring on a day trip", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/blog/que-llevar-a-una-excursion-de-un-dia"}}]}, {"text": ".", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "See all excursions", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/ofertas-de-viajes"}}]}]}]}$j$::jsonb),
('page','2f31e49a-c807-4119-821b-6d2931b93828','en','title',$j$"Privacy policy"$j$::jsonb),
('page','2f31e49a-c807-4119-821b-6d2931b93828','en','seo_title',$j$"Privacy policy | Tripcelona"$j$::jsonb),
('page','2f31e49a-c807-4119-821b-6d2931b93828','en','seo_description',$j$"How Tripcelona handles and protects your personal data when you book a group trip or contact us."$j$::jsonb),
('page','2f31e49a-c807-4119-821b-6d2931b93828','en','content',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Privacy policy", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Last updated: 25 October 2026", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "1. Data controller", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Holder:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"titular\"] (Tripcelona)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tax ID (NIF):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"nif\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Address:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"domicilio\"], Spain", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Email:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"email\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Telephone:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"telefono\"]", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "2. What data we process", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bookings:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " name, surnames, email, telephone, participants' details and billing details.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Contact and quotes:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " the data you send us by form, email or WhatsApp.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Newsletter:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " your email, if you subscribe.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Browsing:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " technical and usage data collected with cookies, according to the ", "type": "text"}, {"text": "Cookie policy", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/politica-de-cookies"}}]}, {"text": ".", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "We do not receive or store your card details: payment is made directly on the bank's secure gateway.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "3. What we use them for and legal basis", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Managing your booking and the excursion", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (contract, art. 6.1.b GDPR).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Answering your enquiries and preparing quotes", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (pre-contractual measures and your consent, art. 6.1.a and 6.1.b GDPR).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Complying with tax and accounting obligations", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (legal obligation, art. 6.1.c GDPR).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sending you the newsletter", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (your consent, which you can withdraw at any time, art. 6.1.a GDPR).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Analysing the use of the website", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (your consent to analytics cookies).", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "4. How long we keep them", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Booking data is kept for as long as the relationship lasts and afterwards for the legal periods (6 years for accounting and tax documentation). Contact data, until your enquiry is resolved and one more year. Newsletter data, until you unsubscribe.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "5. Who we share them with", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "We do not sell or transfer your data. Only the providers we need to deliver the service have access to it, under a data processing agreement:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Banking institution and Redsys, and Stripe, to process payments.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hostinger, for hosting the website.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Our email provider, to send confirmations and replies.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Google, for web analytics if you accept analytics cookies.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Some of these providers may process data outside the European Economic Area. In that case, appropriate safeguards apply, such as the EU-US Data Privacy Framework or the European Commission's standard contractual clauses.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "We may also share data with public authorities when required by law.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "6. Your rights", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "You can exercise your rights of access, rectification, erasure, objection, restriction of processing and portability by writing to [tripola dato=\"email\"], stating which right you are exercising. You can also withdraw your consent at any time.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "If you believe we have not handled your data properly, you can lodge a complaint with the Spanish Data Protection Agency (", "type": "text"}, {"text": "[www.aepd.es](https://www.aepd.es)", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://www.aepd.es"}}]}, {"text": ").", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "7. Security", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "The website uses an encrypted connection (HTTPS) and we apply technical and organisational measures to protect your data against loss, misuse or unauthorised access.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "8. Minors", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Children under 14 cannot provide us with data without the consent of their parents or guardians. Bookings must be made by adults.", "type": "text"}]}]}$j$::jsonb),
('page','7b9293c4-f280-4881-86a6-5a53ac2df0ab','en','title',$j$"Refund policy"$j$::jsonb),
('page','7b9293c4-f280-4881-86a6-5a53ac2df0ab','en','seo_title',$j$"Refund policy | Tripcelona"$j$::jsonb),
('page','7b9293c4-f280-4881-86a6-5a53ac2df0ab','en','content',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Cancellation and refund policy", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Cancellations and refunds", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Last updated: 25 October 2026", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "This policy explains how to cancel a booking and how money is refunded. It complements the ", "type": "text"}, {"text": "General terms and conditions", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/condiciones-de-contratacion"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "1. Cancellation by the customer", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "When you cancel", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Refund", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "More than 15 days before the excursion", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "100% of the amount paid", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "15 days or less before the excursion", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "No refund", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "No-show on the day of the excursion", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "No refund", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "2. How to cancel", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Write to [tripola dato=\"email\"] with your order number and the name of the person who made the booking. We will confirm the cancellation by email. The date that counts is the date we receive your email.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "3. Change of participant", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "You can transfer your place to another person at no cost if you let us know at least 10 days before the excursion, giving the name of the new person.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "4. Cancellation or changes by Tripcelona", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "If we cancel an excursion because of bad weather, for safety reasons or because the minimum number of participants has not been reached, you can choose between a new date or a 100% refund of the amount.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "5. How the refund is made", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "We refund the money to the same card you paid with, within a maximum of 14 days from when the cancellation is approved. The time it takes to appear in your account depends on your bank.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "6. Right of withdrawal", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Excursions are leisure services with a specific date, so the 14-day right of withdrawal (article 103.l of Royal Legislative Decree 1/2007) does not apply. The cancellation conditions on this page apply.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "7. Questions and complaints", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Write to us at [tripola dato=\"email\"] or call us on [tripola dato=\"telefono\"]. Official complaint and claim forms of the Generalitat de Catalunya are available to you: ask us for them and we will send them to you.", "type": "text"}]}]}$j$::jsonb),
