('page','56b615c0-f418-4633-9267-2db8bbcae19a','en','seo_title',$j$"Legal notice | Tripcelona"$j$::jsonb),
('page','56b615c0-f418-4633-9267-2db8bbcae19a','en','content',$j${"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Last updated: 25 October 2026", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "1. Identification details", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "In compliance with article 10 of Law 34/2002 on Information Society Services and Electronic Commerce (LSSI-CE), we provide the details of the owner of this website:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Holder:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"titular\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trade name:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tripcelona", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tax ID (NIF):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"nif\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Address:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"domicilio\"], Spain", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Email:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"email\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Telephone:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"telefono\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Website:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"web\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Activity:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " organisation and sale of day excursions and group activities in Catalonia.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "2. Purpose", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "This legal notice governs the use of the website tripcelona.com. Browsing the site implies acceptance of this notice. The purchase of excursions is also governed by the ", "type": "text"}, {"text": "General terms and conditions", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/condiciones-de-contratacion"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "3. Use of the website", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Users undertake to use the site lawfully and not to damage its operation or that of its systems. Tripcelona may remove comments or content that breach the law or these rules.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "4. Intellectual and industrial property", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "The texts, images, logos, designs and itineraries on this site belong to Tripcelona or are used with the authorisation of their owners. Their reproduction or commercial use without prior written authorisation is not permitted.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "5. Liability", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Tripcelona tries to ensure that the information on the site is correct and up to date, but is not responsible for occasional errors or for service interruptions beyond its control. Nor is it responsible for the content of the external sites it links to.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "6. Data protection and cookies", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "The processing of personal data is explained in the ", "type": "text"}, {"text": "Privacy policy", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/politica-de-privacidad"}}]}, {"text": " and the use of cookies in the ", "type": "text"}, {"text": "Cookie policy", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/politica-de-cookies"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "7. Applicable law and jurisdiction", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "This legal notice is governed by Spanish law. For any dispute with consumers, the courts of the consumer's place of residence shall have jurisdiction.", "type": "text"}]}]}$j$::jsonb),
