('page','4ff03b67-9d9e-42e6-b046-5c650dcc6c80','en','content',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "General terms and conditions", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Last updated: 25 October 2026", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "These conditions govern the purchase of excursions and activities through ", "type": "text"}, {"text": "tripcelona.com", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". To book, you must read and accept them by ticking the corresponding box before paying.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "1. Seller details", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Holder:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"titular\"] (trade name: Tripcelona)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tax ID (NIF):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"nif\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Address:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"domicilio\"], Spain", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Email:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"email\"]", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Telephone:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " [tripola dato=\"telefono\"]", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Tripcelona operates from Spain.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "2. Services", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Tripcelona organises guided day excursions and group activities in Catalonia, departing from Barcelona. Excursions do not include accommodation and last less than 24 hours.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "The page for each excursion states the date, time and departure point, the itinerary, what is and is not included, the number of places and the price.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "3. Purchase process", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Choose the excursion and press ", "type": "text"}, {"text": "«Book a place»", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Review the cart: excursion, date, number of places and total price.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fill in the participants' details on the payment form.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tick the box accepting these conditions and the privacy policy.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Pay by card on the bank's secure gateway.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Once payment is completed you will receive an email with the booking confirmation and your ticket. If you do not receive it within 24 hours, write to us at [tripola dato=\"email\"].", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "4. Prices", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "All prices are shown in ", "type": "text"}, {"text": "euros (€, EUR)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " and include VAT and applicable taxes. The final price is shown before confirming payment and no later charges are added.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "5. Payment methods", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Payment is made at the time of booking by ", "type": "text"}, {"text": "credit or debit card (Visa, Mastercard or Maestro)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " through the secure virtual POS of our bank (Redsys). Payment is encrypted and may require authentication by your bank (3D Secure).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tripcelona does not receive or store your card details: they are entered directly on the bank's payment gateway.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "6. Provision of the service", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "This service involves no physical shipping. The confirmation and ticket are sent by email and the service is provided on the day of the excursion, at the meeting point and time stated on the excursion page. We recommend arriving 15 minutes before departure.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "7. Cancellation by the customer", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "More than 15 days before the excursion:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " 100% refund of the amount.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "15 days or less before the excursion, or no-show:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " no refund.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "To cancel, write to [tripola dato=\"email\"] stating the order number. You can transfer your place to another person at no cost by notifying us at least 10 days before the excursion.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "More details in the ", "type": "text"}, {"text": "Cancellation and refund policy", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/politica-de-devoluciones"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "8. Cancellation or changes by Tripcelona", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Tripcelona may cancel or change the date of an excursion because of bad weather, for safety reasons or because the minimum number of participants stated on the excursion page has not been reached. In that case we will let you know as soon as possible and you will be able to choose between a new date or a 100% refund of the amount.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "9. Right of withdrawal", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "In accordance with article 103.l) of Royal Legislative Decree 1/2007 (General Law for the Defence of Consumers and Users), the 14-day right of withdrawal does not apply to leisure activity services with a specific date of performance, such as our excursions. Cancellations are governed by section 7.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "10. Refunds", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "Refunds are made to the same card used for payment, within a maximum of 14 days from when they are approved. The time it takes for the amount to appear in your account depends on your bank.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "11. Customer service and complaints", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "You can contact us by email at [tripola dato=\"email\"] or by phone and WhatsApp on [tripola dato=\"telefono\"]. We reply within a maximum of 48 working hours.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Official complaint and claim forms of the Generalitat de Catalunya are available to you: request them by email and we will send them to you. You can also go to the Agència Catalana del Consum or the consumer office of your municipality.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "12. Data protection", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "We process your data to manage the booking, as explained in the ", "type": "text"}, {"text": "Privacy policy", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/politica-de-privacidad"}}]}, {"text": ".", "type": "text"}]}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "13. Applicable law and jurisdiction", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"text": "These conditions are governed by Spanish law. For any dispute, the courts of the consumer's place of residence shall have jurisdiction.", "type": "text"}]}]}$j$::jsonb),
