('page','d23cdaa0-478b-4875-b5c0-e0980572cf24','en','content',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Travelling and Exploring Together: Elite Logistics for Your Large Group", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "What you can expect ↓ Vision and Mission Adventure Gallery", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Trust us: Your trip is covered", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Cancelación Flexible para Grupos", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Icon-021.png", "title": null}}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Flexible Cancellation for Groups", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Clear and transparent policies for large groups. We offer flexible cancellation conditions adapted to the logistical needs of your number of travellers.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Reserva 100% Asegurada", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Icon-022.png", "title": null}}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "100% Secured Booking", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Secure, encrypted payment process for all transactions. Your investment is protected, and we guarantee immediate confirmation of all services.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Salud y Seguridad Prioritaria", "src": "https://tripcelona.com/wp-content/uploads/2025/11/Icon-023.png", "title": null}}, {"type": "heading", "attrs": {"level": 4}, "content": [{"text": "Health and Safety First", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Rigorous protocols and guides trained in first aid. We take care of the well-being of each of the 55 members of the group throughout the adventure.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Calidad y Servicio de Confi